    51  /* reads a varint from <raw>'s lowest <b> bits and <len> bytes max (raw included).
    52   * returns the 32-bit value on success after updating raw_in and len_in. Forces
    53   * len_in to (uint32_t)-1 on truncated input.
    54   */
    55  static uint32_t get_var_int(const uint8_t **raw_in, uint32_t *len_in, int b)
    56  {
    57          uint32_t ret = 0;
    58          int len = *len_in;
    59          const uint8_t *raw = *raw_in;
    60          uint8_t shift = 0;
    61
    62          len--;
    63          ret = *(raw++) & ((1 << b) - 1);
    64          if (ret != (uint32_t)((1 << b) - 1))
    65                  goto end;
    66
    67          while (len && (*raw & 128)) {
    68                  ret += ((uint32_t)(*raw++) & 127) << shift;
    69                  shift += 7;
    70                  len--;
    71          }
    72
    73          /* last 7 bits */
    74          if (!len)
    75                  goto too_short;
    76          len--;
    77          ret += ((uint32_t)(*raw++) & 127) << shift;
    78
    79   end:
    80          *raw_in = raw;
    81          *len_in = len;
    82          return ret;
    83
    84   too_short:
    85          *len_in = (uint32_t)-1;
    86          return 0;
    87  }
