   120          out.len = in.len;
   121          out.ptr = chunk_newstr(store);
   122          if (unlikely(!isttest(out)))
   123                  return out;
   124
   125          if (unlikely(store->data + out.len > store->size)) {
   126                  out.ptr = NULL;
   127                  return out;
   128          }
   129
   130          store->data += out.len;
   131          memcpy(out.ptr, in.ptr, out.len);
   132          return out;
   133  }
